import {hdDimensions} from './pattern-hd-core.js';
import {ImageAssistant} from './textile-tools-ai.js';
import {imageThumbnail} from './textile-ai-images.js';
import {canvas,pixels,putPixels,loadImage,canvasEdgeDifference} from './textile-tools-image.js';
const $=id=>document.getElementById(id);
export function mountHD(tool,{panel,field,select,single}){
  const state=panel(tool,'<div class="tt-ai-workflow"><span>01 上传花型</span><span>02 AI 保守修复</span><span>03 对比后放大</span></div><details class="tt-hd-ai" open><summary>✦ AI 保守修复 · 推荐先做</summary><p class="tt-help">让 AI 减少压缩噪点、理清已有纹样边缘。原色、花形与排布优先保留，模糊处不凭空补花；候选先对比，确认后才作为放大底图。</p>'+field('hdAIIntent','希望重点修复 · 选填','<textarea id="hdAIIntent" maxlength="500" placeholder="例如：去掉压缩噪点，理清小叶边缘，保留细线和原来的蓝色。"></textarea>')+'<button id="hdAIStart" class="tt-primary" disabled>✦ AI 生成保守修复候选</button><div class="tt-inline-buttons"><button id="hdAICheck" class="tt-secondary">检查任务</button><button id="hdAICancel" class="tt-secondary">停止 / 清除检查</button></div><p id="hdAIStatus" class="tt-status" role="status" aria-live="polite">上传后点击 AI 修复，使用当前图片服务，按服务计费。</p><div id="hdAIResult" hidden><img id="hdAIImage" alt="待确认的 AI 花型修复候选图"><p class="tt-help" id="hdAICandidateMeta"></p><button id="hdAIAdopt" class="tt-primary">采用候选并放大</button><p class="tt-help">先用大图“原图 / AI 候选”检查花形、色彩和细线。AI 修复并不保证恢复真实细节。</p></div></details><div class="tt-divider"></div><h3 style="font-size:14px;margin:0 0 14px">交付尺寸与辅助调整</h3>'+field('hdScale','放大倍数',select('hdScale',[['2','2 倍'],['4','4 倍'],['1','原尺寸 · 只调整锐度']]))+field('hdSharpness','辅助锐度 <b id="hdSharpnessValue">20%</b>','<input id="hdSharpness" type="range" min="0" max="100" value="20">','过高可能强调噪点，请用 100% 视图确认。')+'<label class="tt-check"><input id="hdSeamless" type="checkbox">原图为循环花型 · 环绕采样边缘</label><p class="tt-help" id="hdDimensions">上传后显示原图与交付尺寸。</p><button id="hdRun" class="tt-secondary" disabled style="margin-top:10px">仅本机放大原图 · 不使用 AI</button><button id="hdResetSource" class="tt-secondary" disabled style="margin-top:8px">恢复原图作为底图</button><button id="hdStop" class="tt-secondary tt-stop" hidden style="margin-top:10px">停止本机处理</button><p class="tt-help">放大使用本机插值与受限锐化，负责输出尺寸，不会创造原图没有的真实细节。</p>',{actions:'<div class="tt-hd-preview-tabs" role="group" aria-label="选择高清对比版本"><button id="hdPreviewOriginal" class="tt-secondary" aria-pressed="true" disabled>原图</button><button id="hdPreviewCandidate" class="tt-secondary" aria-pressed="false" disabled>AI 候选</button><button id="hdPreviewFinal" class="tt-secondary" aria-pressed="false" disabled>高清结果</button></div><button id="hdCompare" class="tt-secondary" aria-pressed="false" disabled>查看原图</button><button id="hdZoom" class="tt-secondary" aria-pressed="false" disabled>100% 检查</button>'});
  let source=null,base=null,candidate=null,output=null,worker=null,display='original',zoom=false,aiBusy=false,adopting=false,candidateValid=false,baseIsAI=false;
  function preview(){if(!source)return;const image=display==='candidate'?candidate:display==='final'?output:source;if(!image)return;const target=$('hdCanvas');target.width=image.width;target.height=image.height;target.getContext('2d').drawImage(image,0,0);target.style.maxWidth=zoom?'none':'';target.style.maxHeight=zoom?'none':'';target.style.width=zoom?image.width+'px':'';target.style.height=zoom?image.height+'px':'';$('hdStage').classList.toggle('tt-pixel-zoom',zoom);const names={original:'原图 · 保留未覆盖',candidate:'AI 修复候选 · 待核对',final:baseIsAI?'AI 修复后 · 本机放大结果':'原图 · 本机放大结果'};$('hdPreviewMeta').textContent=names[display]+` · ${image.width} × ${image.height} px`;for(const [id,value]of [['hdPreviewOriginal','original'],['hdPreviewCandidate','candidate'],['hdPreviewFinal','final']])$(id).setAttribute('aria-pressed',String(display===value));$('hdCompare').setAttribute('aria-pressed',String(display==='original'));$('hdCompare').textContent=display==='original'&&(output||candidate)?'返回最新结果':'查看原图';}
  function dimensions(){if(!base)return false;try{const size=hdDimensions(base.width,base.height,Number($('hdScale').value));$('hdDimensions').textContent=`${baseIsAI?'AI 修复底图':'原图'} ${base.width} × ${base.height} → ${size.width} × ${size.height} px`;$('hdAIAdopt').textContent='采用候选并 '+$('hdScale').value+' 倍交付';return true;}catch(error){$('hdDimensions').textContent=error.message;return false;}}
  function sync(){state.workflowAdopted=baseIsAI&&!!output;state.busy=!!worker||aiBusy||adopting;const locked=state.busy;for(const control of state.element.querySelectorAll('input,select,textarea'))control.disabled=locked;$('hdChoose').disabled=$('hdEmptyUpload').disabled=locked;$('hdAIStart').disabled=locked||!source;$('hdRun').disabled=locked||!base||!dimensions();$('hdRun').textContent=baseIsAI?'仅本机处理当前 AI 底图':'仅本机放大原图 · 不使用 AI';$('hdResetSource').disabled=locked||!baseIsAI;$('hdAIAdopt').disabled=locked||!candidate||!candidateValid;$('hdStop').hidden=!worker;$('hdStop').disabled=!worker;$('hdAICheck').disabled=$('hdAICancel').disabled=!!worker||adopting;$('hdPreviewOriginal').disabled=$('hdCompare').disabled=$('hdZoom').disabled=!source;$('hdPreviewCandidate').disabled=!candidate;$('hdPreviewFinal').disabled=!output;state.changed();}
  function invalidate(){if(worker)return;output=null;state.output=null;display=baseIsAI&&candidate?'candidate':'original';preview();sync();}
  state.loadFiles=async files=>{if(aiBusy||worker||adopting)return;await single(state,files,image=>{source=base=image.canvas;candidate=output=null;candidateValid=baseIsAI=false;state.output=null;display='original';zoom=false;$('hdAIResult').hidden=true;$('hdAIImage').removeAttribute('src');$('hdZoom').setAttribute('aria-pressed','false');$('hdZoom').textContent='100% 检查';preview();state.status('原尺寸工作稿已保留；AI 参考单独缩至最长边 2048 px，不覆盖本机原稿。先点击 AI 修复生成候选，确认花形与颜色，再采用并放大。');},Infinity);sync();};
  async function run(){if(!base||worker||aiBusy)return;try{hdDimensions(base.width,base.height,Number($('hdScale').value));}catch(error){state.status(error.message,true);return;}state.status((baseIsAI?'正在放大已确认的 AI 修复底图':'正在本机放大原图')+'…');worker=new Worker('/pattern-hd-worker.js',{type:'module'});sync();const data=pixels(base),options={scale:Number($('hdScale').value),sharpen:Number($('hdSharpness').value)/100,seamless:$('hdSeamless').checked};
    function finish(){worker?.terminate();worker=null;sync();}
    worker.onmessage=event=>{if(event.data.error){state.status(event.data.error,true);finish();}else if(event.data.result){output=canvas(event.data.result.width,event.data.result.height);putPixels(output,event.data.result);state.output=output;display='final';preview();state.status(`处理完成：${output.width} × ${output.height} px。${baseIsAI?'已使用确认的 AI 修复候选。':'使用原图本机放大。'}${$('hdSeamless').checked?'循环边缘差异 '+canvasEdgeDifference(base).toFixed(1)+'% → '+canvasEdgeDifference(output).toFixed(1)+'%（仅供检查）。':''}请在原图、候选和高清结果间对比，再下载。`);finish();}else if(event.data.progress!=null)state.status('本机放大 '+event.data.progress+'%…');};worker.onerror=()=>{state.status('本机处理失败，原图与候选保留，请减小图片或倍数。',true);finish();};$('hdStop').onclick=()=>{finish();state.status('已停止本机处理，原图与 AI 候选保留，可重新处理。');};worker.postMessage({source:{width:base.width,height:base.height,data:data.data},options},[data.data.buffer]);}
  $('hdRun').onclick=()=>void run();$('hdScale').onchange=invalidate;$('hdSharpness').oninput=()=>{$('hdSharpnessValue').textContent=$('hdSharpness').value+'%';invalidate();};$('hdSeamless').onchange=invalidate;$('hdResetSource').onclick=()=>{if(state.busy)return;base=source;baseIsAI=false;invalidate();state.status('已恢复原图作为处理底图；AI 候选仍可对比，原稿没有覆盖。');};
  for(const [id,value]of [['hdPreviewOriginal','original'],['hdPreviewCandidate','candidate'],['hdPreviewFinal','final']])$(id).onclick=()=>{display=value;preview();};$('hdCompare').onclick=()=>{display=display==='original'?(output?'final':candidate?'candidate':'original'):'original';preview();};$('hdZoom').onclick=()=>{zoom=!zoom;$('hdZoom').setAttribute('aria-pressed',String(zoom));$('hdZoom').textContent=zoom?'适应画布':'100% 检查';preview();};
  const assistant=new ImageAssistant({storageKey:'zhijing-hd-ai-pending-v1',status:message=>$('hdAIStatus').textContent=message,busy:busy=>{aiBusy=busy;sync();},result:async(url,{isCurrent=()=>true}={})=>{try{const response=await fetch(url);if(!response.ok)throw Error('修复候选无法读取，请检查任务后重试');const loaded=await loadImage(new File([await response.blob()],'AI修复候选.png',{type:'image/png'}),Infinity);if(!isCurrent())return;if(!source){const originalURL=url.replace(/\/images\/[a-f0-9-]{36}$/,'/images/original'),original=await fetch(originalURL);if(!original.ok)throw Error('对应原图暂时无法恢复，请稍后再次检查任务');const restored=await loadImage(new File([await original.blob()],'已恢复任务原图.png',{type:'image/png'}),Infinity);if(!isCurrent())return;source=base=restored.canvas;baseIsAI=false;state.ready();$('hdFileInfo').textContent='已恢复任务原图 · '+source.width+' × '+source.height+' px';state.status('已恢复原图与 AI 修复候选，可继续对比和采用，没有重新生成。');}if(!isCurrent())return;candidate=loaded.canvas;$('hdAIImage').src=url;$('hdAIResult').hidden=false;candidateValid=Math.abs(candidate.width/candidate.height/(source.width/source.height)-1)<.035;$('hdAICandidateMeta').textContent=`候选 ${candidate.width} × ${candidate.height} px。`+(candidateValid?'请检查花形和色彩；采用前不会覆盖原图。':'候选长宽比与原图不一致，为避免拉伸花形，暂不能采用。');display='candidate';preview();sync();}catch(error){if(!isCurrent())return;state.status(error.message,true);throw error;}}});
  $('hdAIStart').onclick=async()=>{if(!source||state.busy)return;const intent=$('hdAIIntent').value.trim();candidate=null;candidateValid=false;$('hdAIResult').hidden=true;display='original';preview();sync();await assistant.start(imageThumbnail(source,2048),'Repair this flat textile print image conservatively: reduce compression artifacts and clarify existing motif edges only. Preserve exact motif geometry, text shapes, repeat scale, spacing and every original color. Do not invent additional floral details, change motifs, add shadows, simulate fabric folds or add borders. Return a flat reference-faithful print artwork with the same aspect ratio. If a detail is ambiguous, leave it unchanged.'+(intent?' User repair priorities (preserve all unrequested properties): '+intent:''),{title:'花型高清 · AI 保守修复候选',lockPattern:true});};$('hdAICheck').onclick=()=>assistant.check();$('hdAICancel').onclick=()=>assistant.cancel();
  $('hdAIAdopt').onclick=async()=>{if(!candidate||!candidateValid||state.busy)return;try{hdDimensions(candidate.width,candidate.height,Number($('hdScale').value));base=candidate;baseIsAI=true;output=null;state.output=null;display='candidate';preview();sync();await run();}catch(error){state.status(error.message,true);}};
  window.addEventListener('pagehide',()=>worker?.terminate());sync();return state;
}
